// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _test(uint256 playValue) internal {
        playValue = bound(playValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(playValue == 10);
        vm.assume(c.pot() + 10 > c.pot());
        uint256 random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        vm.assume(random != 0);
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        try c.play{value: playValue}() {} catch { return; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        assertTrue(potAfter == potBefore + 10);
    }

    function testFuzz_test(uint256 playValue) public {
        _test(playValue);
    }

    receive() external payable {}
}
